------------ Init ------------

function SkillPoolOperationMgr:Init()
    self:CleanProperty()
    self.listSkillCardWillDelete = {}
    self:AddListener()
end

function SkillPoolOperationMgr:Delete()
    self:RemoveListener()
    if self.coShowSwallowClick then
        cs_coroutine.stop(self.coShowSwallowClick)
    end
    self:CleanProperty()
end

function SkillPoolOperationMgr:CleanProperty()
    self.teSkillCardOrigin = nil -- Type_Eat_Card_Origin
    --self.teSkillCardTarget = nil -- Type_Eat_Card_Target
    self.goEffectOrigin = nil
    self.goEffectTarget = nil
    self.coShowSwallowClick = nil
    self.listAvailableRole = nil
    self.listSkillCardWillDelete = nil
    self.eventInputFinish = nil
end

function SkillPoolOperationMgr:AddListener()
    self.eventInputFinish = Events.AddListener(Constants.EventNames.BattleInputFinished, Bind(self, self.ActionOnInputFinished))
end

function SkillPoolOperationMgr:RemoveListener()
    if not IsNull(self.eventInputFinish) then
        Events.RemoveListener(Constants.EventNames.BattleInputFinished, self.eventInputFinish)
    end
end

function SkillPoolOperationMgr:ActionOnInputFinished()
    local listPanel = { [Constants.UITypeIds.UIBattlingEatCard] = 1, 
                        [Constants.UITypeIds.UIBattlingPickCard] = 1, 
                        [Constants.UITypeIds.UIBattlingDiscoverCard] = 1, }
    
    local dialogs = UIModule.CurrentScreen.dialogs
    for i, v in pairs(dialogs) do
        if listPanel[checkNumber(v.Argument.id)] then
            local lbDialog = v
            if not IsNull(lbDialog) then
                local ltDialog = lbDialog.Env
                ltDialog.runCloseAction = true
                UIModule.CloseDialog(lbDialog)
            end
        end
    end
end

