---OriginCardEatCardShow
---卡牌吞噬时 使用卡牌 的表现
---@param skillCardOrigin UIBattlingSkillCardsNode
function SkillPoolOperationMgr:OriginCardEatCardShow(skillCardOrigin)
    if isNull(skillCardOrigin) then return end
    -- print("->SkillPoolOperationMgr:OriginCardEatCardShow:", self.teSkillCardOrigin, self.goEffectOrigin)
    if isNull(self.teSkillCardOrigin) then
        self.teSkillCardOrigin = skillCardOrigin
    end
    if isNull(self.goEffectOrigin) then
        self.goEffectOrigin = UIBattlingTools.ReloadPoolObjGO(Constants.UIBattlingObjPoolPrefabs.EatCardOrigin, self.teSkillCardOrigin.ParticalRoot.gameObject)
    end 
    if not IsNull(self.goEffectOrigin) then
        local animatorOrigin = self.goEffectOrigin.transform:Find("AnimRoot"):GetComponent(typeof(Animator))
        animatorOrigin:Play(A_EAT_ORIGIN_GO)
        cs_coroutine.yield_return(WaitForSeconds(0.2))
    end
    self:CleanDeletedCard()
    self:RecycleGOEffectOrigin()
    self.teSkillCardOrigin = nil
end

function SkillPoolOperationMgr:RecycleGOEffectOrigin()
    if not IsNull(self.goEffectOrigin) then
        UIBattlingTools.RecyclePoolObj(self.goEffectOrigin)
        self.goEffectOrigin = nil
    end
end

