---EatCardOnClick
---有吞噬效果的卡牌被点击时的表现
---@param skillCardOrigin UIBattlingSkillCardsNode
function SkillPoolOperationMgr:EatCardOnClick(skillCardOrigin)
    self.coShowSwallowClick = cs_coroutine.start(function()
        local battlingDialog = UIBattlingCtrlMgr:GetInstance():GetBattlingDialog()
        battlingDialog:SetRootSkillPoolInteractable(false)
        self.teSkillCardOrigin = skillCardOrigin
        self.goEffectOrigin = UIBattlingTools.ReloadPoolObjGO(Constants.UIBattlingObjPoolPrefabs.EatCardOrigin, self.teSkillCardOrigin.ParticalRoot.gameObject)
        local resultCheck = self:CheckSkillPoolCanEatCard()
        local animatorOrigin = self.goEffectOrigin.transform:Find("AnimRoot"):GetComponent(typeof(Animator))
        animatorOrigin:Play(resultCheck and A_EAT_ORIGIN_PREPARE or A_EAT_ORIGIN_PASS)
        --cs_coroutine.yield_return(WaitForSeconds(0.5))
        if resultCheck then
            --- 设置无法吞噬的卡牌
            self.lisDisableNode = {}
            for i, skillCard in ipairs(self.listSPCard) do
                local disableNode = UIBattlingTools.ReloadPoolObjGO(Constants.UIBattlingObjPoolPrefabs.GO_EAT_CARD_DISABLE_NODE, skillCard.ParticalRoot.gameObject)
                table.insert(self.lisDisableNode, disableNode)
            end
            --- 控制 skillPool 画布层级
            local _setSkillPoolCanvas = function(overrideSorting, sortingOrder)
                local skillPool = battlingDialog.luaTableDialogSkillPool
                local canvasSkillPool = skillPool.controller.gameObject:EnsureComponent(typeof(CS.UnityEngine.Canvas))
                canvasSkillPool.overrideSorting = overrideSorting
                canvasSkillPool.sortingOrder = sortingOrder
            end
            _setSkillPoolCanvas(true, 100)
            UIModule.OpenDialog({id = Constants.UITypeIds.UIBattlingEatCard, parameters = { callBack = function()
                _setSkillPoolCanvas(false, 0)
                self:CleanListDisableNode()
            end, callBackCancel = function()
                self:CleanEatCardElement()
                if skillCardOrigin then
                    skillCardOrigin:SetEventReceiverEnableState(true)
                end
            end, cardBehaviour = Constants.CardBehavior.Swallow }}) -- 展示吞卡界面
        else
            local skillCardPosData = { skillCardOrigin.curTransArrLinePos, skillCardOrigin.curTransArrLine }
            local data2Logic = { pos = skillCardPosData, params = nil }
            
            xTry(function()
                local _skillCardData = skillCardOrigin.skillCardData
                local _skillCardId = _skillCardData.skillId
                local _skillCardDConfigData = UIBattlingTools.GetSkillCardInfoByTwoParam(_skillCardId)
                local skillClickType = _skillCardDConfigData.clickType --技能点选规则（1、友方；2、敌方；3、全体；4、自身）
                local isEveryone = _skillCardDConfigData.isEveryone --是否无需点选（0、需点选；1、不需点选）
                local conditionNeed2FillAttackTarget = not checkBool(skillClickType == 1 and (not isEveryone))
                if conditionNeed2FillAttackTarget then
                    battlingDialog = UIBattlingCtrlMgr:GetInstance().tableBattlingDialog
                    if battlingDialog and (not isNull(battlingDialog.curAttTargetId)) then
                        data2Logic.targetId = checkNumber(battlingDialog.curAttTargetId)
                    end
                end
                -- print("->SkillPoolOperationMgr:EatCardOnClick:", conditionNeed2FillAttackTarget, table.dump(checkTable(data2Logic)))
            end)
            Events.Broadcast(Constants.EventNames.BattleInputUse, data2Logic)
            self:CleanEatCardElement()
        end
        battlingDialog:SetRootSkillPoolInteractable(true)
        self.coShowSwallowClick = nil
    end)
end


