function SkillPoolOperationMgr:CleanListDisableNode()
    if self.lisDisableNode then
        for i, node in pairs(self.lisDisableNode) do
            UIBattlingTools.RecyclePoolObj(node)
        end
        self.lisDisableNode = nil
    end
end

---CheckSkillPoolCanEatCard
---检查当前牌库的可吞噬状态
function SkillPoolOperationMgr:CheckSkillPoolCanEatCard()
    local skillPool = UIBattlingCtrlMgr:GetInstance().tableBattlingDialog.luaTableDialogSkillPool
    local listSkillCard = {}
    self.listSPCard = {}
    local lineTop = skillPool.skillPoolTransArrLineTop
    local lineDown = skillPool.skillPoolTransArrLineDown
    local checkSkillLine = function(line, list)
        if isNull(list) then list = {} end
        for i, skillLocal in ipairs(line) do
            if not IsNull(skillLocal) then
                table.insert(list, skillLocal.luaBehaviour)
            end
        end
    end
    checkSkillLine(lineTop, listSkillCard)
    checkSkillLine(lineDown, listSkillCard)
    if #listSkillCard <= 0 then return false end
    local _coLinePos, _coLine
    if self.teSkillCardOrigin then
        _coLinePos = self.teSkillCardOrigin.curTransArrLinePos
        _coLine = self.teSkillCardOrigin.curTransArrLine
    end
    for i, skillLocal in fipairs(listSkillCard) do
        local skillCard = skillLocal.Env
        local isSPCard = skillCard.isSPSkill -- SP 卡无法吞噬
        local linePos = skillCard.curTransArrLinePos
        local line = skillCard.curTransArrLine
        local sameLocation = _coLinePos == linePos and line == _coLine
        if isSPCard and (not sameLocation) then
            table.insert(self.listSPCard, skillCard)
            table.remove(listSkillCard, i)
        end
        if sameLocation then -- 排除自己
            table.remove(listSkillCard, i)
        end
    end 
    -- print("->SkillPoolOperationMgr:CheckSkillPoolCanEatCard", table.dump(listSkillCard), table.dump(self.listSPCard))
    return #listSkillCard > 0
end

