------------ DiscoverCard ------------

function SkillPoolOperationMgr:DiscoverCardOnClick(skillCard, skillCardPosData, cardBehaviorParam)
    self.listAvailableRole = {}
    local roleId = skillCard.skillCardRoleId
    local roleViews = BattleViewMgr.roleViews
    local listAvailableRole = {}
    for i = 1, #roleViews do
        local roleView = roleViews[i]
        if roleView then
            local roleCampType = roleView.camp
            local isDead = roleView:IsDead()
            local condition = BattleInfo:IsUserCamp(roleCampType) and roleView.isPlayer and (not isDead) and roleView.id ~= roleId
            if condition then
                table.insert(listAvailableRole, roleView)
            end
        end
    end
    self.listAvailableRole = listAvailableRole
    if isNull(listAvailableRole) or #listAvailableRole < 1 then
        UIBattlingCtrlMgr:GetInstance().tableBattlingDialog:OnSkillCardClickCommon(skillCard, skillCardPosData)
    else
        UIModule.OpenDialog({ id = Constants.UITypeIds.UIBattlingDiscoverCard, parameters = {
            skillCard = skillCard, cardBehaviorParam = cardBehaviorParam,
            callBack = function(data2Logic)
                UIBattlingCtrlMgr:GetInstance().tableBattlingDialog:OnSkillCardClickCommon(skillCard, skillCardPosData, data2Logic and data2Logic.params or nil)
            end, callBackCancel = function()
                if skillCard then
                    skillCard:SetEventReceiverEnableState(true)
                end
            end }})
    end
end

